styles.css:
.wp-block-button__link:hover, .wp-block-button__link:focus-visible, .wp-block-tab-list button:hover, .wp-block-tab-list button:focus-visible { background-color: #8ed0ff !important; border-color: #8ed0ff !important; color: #071426 !important; transition: background-color .18s ease, border-color .18s ease, color .18s ease; }
#provider-categories .wp-block-tab-list button { background:#fff !important; border:1px solid #dbe5f1 !important; border-radius:5px !important; color:#0b63f6 !important; box-shadow:none !important; }
#provider-categories .wp-block-tab-list button::before { content:none !important; border:0 !important; }
#provider-categories .wp-block-tab-list button[aria-selected="true"] { background:#e5e7eb !important; border-color:#e5e7eb !important; color:#071426 !important; }
#provider-categories .wp-block-tab-list button:hover, #provider-categories .wp-block-tab-list button:focus-visible { background:#8ed0ff !important; border-color:#8ed0ff !important; color:#071426 !important; }
#provider-categories .wp-block-tab-list button:focus-visible { outline:2px solid #0b63f6 !important; outline-offset:2px; }
#provider-categories .wp-block-tab-list button:focus:not(:focus-visible) { outline:none !important; }
#provider-categories .sky-provider-grid { grid-template-columns:repeat(3,minmax(0,1fr)) !important; }
@media (max-width:700px) { #provider-categories .sky-provider-grid { grid-template-columns:repeat(2,minmax(0,1fr)) !important; } }
#provider-categories .cb-carousel-block .swiper-button-next:hover, #provider-categories .cb-carousel-block .swiper-button-prev:hover { color:#8ed0ff !important; }
header a[href^="tel:"] { text-decoration:none !important; }
header a[href^="tel:"]:hover, header a[href^="tel:"]:focus-visible { text-decoration:none !important; }
#provider-categories .wp-block-tab-list { border:0 !important; box-shadow:none !important; background:transparent !important; }
#provider-categories .wp-block-tab-list button { border:1px solid #dbe5f1 !important; box-shadow:none !important; }
#provider-categories .wp-block-tab-list button[aria-selected="true"] { background:#e5e7eb !important; border-color:#e5e7eb !important; color:#071426 !important; }
#provider-categories .wp-block-tab-list button:hover { background:#8ed0ff !important; border-color:#8ed0ff !important; color:#071426 !important; }
#provider-categories .sky-provider-grid { min-height:500px; grid-auto-rows:1fr; align-content:stretch; }
#provider-categories .sky-provider-grid > .wp-block-group { min-height:150px; }
@media (max-width:782px) { #provider-categories .sky-provider-grid { min-height:0 !important; grid-auto-rows:auto; grid-template-columns:repeat(2,minmax(0,1fr)) !important; } }
#contacts .wp-block-social-links .wp-social-link a { width:38px; height:38px; display:flex; align-items:center; justify-content:center; }
#contacts .wp-block-social-links .wp-social-link svg { width:26px !important; height:26px !important; }
#provider-categories .sky-provider-grid { grid-template-columns:repeat(12,minmax(0,1fr)) !important; }
#provider-categories .sky-provider-grid > .wp-block-group { grid-column:span 4; }
#provider-categories .sky-provider-grid--7 > .wp-block-group:nth-child(-n+4), #provider-categories .sky-provider-grid--8 > .wp-block-group { grid-column:span 3; }
@media (max-width:782px) { #provider-categories .sky-provider-grid { grid-template-columns:repeat(2,minmax(0,1fr)) !important; } #provider-categories .sky-provider-grid > .wp-block-group { grid-column:auto !important; } }
